name = "Tiện Ích Client"
description = [[
Phiên bản 1.0 - Tiện Ích Client

★ Tự động đi bộ đến điểm chọn trên bản đồ, có chỉ dẫn đường đi.
★ Camera quan sát: đổi góc nhìn, ẩn HUD và theo dõi mục tiêu.
★ Bổ sung biểu tượng sinh vật, vật phẩm và công trình trên bản đồ.
★ Thả vật phẩm theo lưới; ẩn hình vật phẩm để thấy rõ điểm thả.
★ Đặt công trình theo lưới với nhiều kiểu hình học và màu hiển thị.

Chỉ cần cài phía Client.

]]
author = "Nyx"
version = "1.0.3"
api_version = 10
api_version_dst = 10
dst_compatible = true
all_clients_require_mod = false
client_only_mod = true
server_only_mod = false
priority = -10
icon_atlas = "modicon.xml"
icon = "modicon.tex"

local yes_no = {
    {description = "Bật", data = true},
    {description = "Tắt", data = false},
}
local function heading(label)
    return {name = "", label = label, options = {{description = "", data = 0}}, default = 0}
end

