for i = 1, #configuration_options do
    local option = configuration_options[i]
    if option.name ~= "" then
        option.label = labels[option.name] or option.label
        option.hover = explanations[option.name] or option.hover
        for j = 1, #(option.options or {}) do
            local choice = option.options[j]
            choice.description = choice_text[choice.description] or choice.description
        end
    end
end
